/* Fibonacci test   Byte Jul.87 p.102   typed by O.E.Tutzauer */     #define NTIMES	10#define NUMBER  24main()	{	int i;	unsigned value, fib();		printf("start \n");		for (i=1; i<= NTIMES; i++)	value = fib(NUMBER);		printf("%d loops done \n",NTIMES);	printf(" Fibonacci( %d) = %u \n",NUMBER, value); 	exit(0);	}unsigned fib(x)int x;	{		if(x>2)			return (fib(x-1) + fib (x-2));		else			return(1);	 } 